//문자열 길이 체크

scwin.vScrenID = "ULDSTF05303.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vSecugrpID;
scwin.TR_JOB;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.rowPos;
scwin.pJsMarket = js_market;
scwin.gDepCd;
scwin.gBasIdx;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_SearchIsu.src = "../img/btn_search.gif";
        img_SearchIsu.setDisabled(false);
    } else if (initTyp == "X") {
        img_SearchIsu.src = "../img/btn_search_d.gif";
        img_SearchIsu.setDisabled(true);
    }
};
scwin.fn_initLabel = function(secugrpId) {
    //alert ('[secugrpId]'+secugrpId);
    if (secugrpId == SECUGRP_ID_EF) {
        edt_ETF_FLOW_NETASST_TOTAMT.setReadOnly(true);
        edt_ETF_FLOW_NETASST_TOTAMT.readonlybackcolor = '#b9d4f7';
        edt_ETF_FORNCURR_NETASST_TOTAMT.setReadOnly(true);
        edt_ETF_FORNCURR_NETASST_TOTAMT.readonlybackcolor = '#b9d4f7';
        edt_ETF_FORNFLOW_NETASST_TOTAMT.setReadOnly(true);
        edt_ETF_FORNFLOW_NETASST_TOTAMT.readonlybackcolor = '#b9d4f7';
        edt_ETF_FORNCURR_LST_NAV.setReadOnly(true);
        edt_ETF_FORNCURR_LST_NAV.readonlybackcolor = '#b9d4f7';
        edt_FLOW_SHRS.setReadOnly(true);
        edt_FLOW_SHRS.readonlybackcolor = '#b9d4f7';
    }
};
scwin.fn_initCreditGrid = function(dstObj, idx, cd, nm) {
    dstObj.AddRow();
    dstObj.setCellData(idx, "CREDIT_VALU_INST_TP_CD", cd);
    dstObj.setCellData(idx, "CREDIT_VALU_INST_TP_NM", nm);
};


/* 기초지수 및 기초시장,기초자산,추적배수 조회 */
scwin.fn_searchBasIdxClss = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETP_BAS_IDX_COMPST_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.etpbasidxcopmpst.select.list.condition";
    dts_basIdxClss.DataID = encodeURI(url);
    dts_basIdxClss.reset();
    $c.stf.CopyDataSet(dts_basIdxClss, dts_refIdx);
};
scwin.fn_searchCode = function() {
    /*
    00685-명의개서대행기관
    01393-ETF구분코드	
    02208   추적기초자산단위코드 (위안,유로,파운드,엔)
    02323 - 과세유형(증권거래세,배당소득세)
    03242 - ETF복제방법구분코드(실물,합성,Active)
    */
    var arrCid = [{
        cid: "TRANSSTK_AGNT_CD",
        cnm: "cmb_TRANSSTK_AGNT_CD"
    }, {
        cid: "ETF_TP_CD",
        cnm: "cmb_ETF_TP_CD"
    }, {
        cid: "TRACE_ULY_UNIT_CD",
        cnm: "cmb_TRACE_ULY_UNIT_CD"
    }, {
        cid: "TAX_TP_CD",
        cnm: "cmb_TAX_TP_CD"
    }, {
        cid: "ETF_REPLICA_METHD_TP_CD",
        cnm: "cmb_ETF_REPLICA_METHD_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='TRANSSTK_AGNT_CD','ETF_TP_CD','TRACE_ULY_UNIT_CD','TAX_TP_CD','ETF_REPLICA_METHD_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_disableDistrMmDd = function() {
    var ori_btnSave = btn_Save.src;
    var ori_btn_Update = btn_Update.src;
    var chk_btnSave = "btn_save.gif";
    var chk_btn_Update = "btn_modify.gif";
    if ((ori_btnSave.indexOf(chk_btnSave) == -1) && (ori_btn_Update.indexOf(chk_btn_Update) == -1)) {
        img_Add.src = "../img/btn_arrowR_d.gif";
        img_del.src = "../img/btn_arrowL_d.gif";
        img_Add.setDisabled(true);
        img_del.setDisabled(true);
    } else {
        img_Add.src = "../img/btn_arrowR.gif";
        img_del.src = "../img/btn_arrowL.gif";
        img_Add.setDisabled(false);
        img_del.setDisabled(false);
    }
};
scwin.fn_getDistrBasMmDd = function() {
    if (dts_IsuItem.getTotalRow() > 0) {
        for (var i = 1; i <= 12; i++) {
            if (dts_IsuItem.getCellData(1, "EARNG_DISTR_BAS_MMDD" + i) != "") {
                dts_DISTR_BAS_MMDD.insertRow();
                dts_DISTR_BAS_MMDD.setCellData(i, "EARNG_DISTR_BAS_MMDD", dts_IsuItem.getCellData(1, "EARNG_DISTR_BAS_MMDD" + i));
            }
        }
        scwin.fn_DistrBasMmDdSetting(dts_DISTR_BAS_MMDD.getRowPosition());
    }
};
scwin.fn_DistrBasMmDdSetting = function(rPos) {
    if (dts_DISTR_BAS_MMDD.getTotalRow() > 0) {
        $c.stf.setObjectValue(txb_DISTR_BAS_MMDD, dts_DISTR_BAS_MMDD.getCellData(rPos, "EARNG_DISTR_BAS_MMDD"));
    }
};
scwin.fn_addDistrBasMmDd = function() {
    if (dts_DISTR_BAS_MMDD.getTotalRow() > 11) {
        $c.win.alert("[분배기준일]은  최대12개 입니다.");
        return false;
    } else {
        if (scwin.fn_dateCheck()) {
            grd_DISTR_BAS_MMDD.Redraw = false;
            dts_DISTR_BAS_MMDD.insertRow();
            dts_DISTR_BAS_MMDD.setCellData(dts_DISTR_BAS_MMDD.getRowPosition(), "EARNG_DISTR_BAS_MMDD", $c.stf.getObjectValue(txb_DISTR_BAS_MMDD));
            grd_DISTR_BAS_MMDD.Redraw = true;
        }
    }
};
scwin.fn_delDistrBasMmDd = function() {
    if (dts_DISTR_BAS_MMDD.getTotalRow() < 1) {
        $c.win.alert("삭제할 [분배기준일]이 없습니다.");
        return false;
    } else {
        $c.cp.removeRow(dts_DISTR_BAS_MMDD, dts_DISTR_BAS_MMDD.getRowPosition());
        scwin.fn_DistrBasMmDdSetting(dts_DISTR_BAS_MMDD.getRowPosition());
    }
};
scwin.fn_SaveDistrBasMmDd = function() {
    for (var i = 1, j = 12; i <= j; i++) {
        dts_IsuItem.setCellData(1, "EARNG_DISTR_BAS_MMDD" + i, dts_DISTR_BAS_MMDD.getCellData(i, "EARNG_DISTR_BAS_MMDD"));
    }
};
scwin.fn_dateCheck = function() {
    if ($c.stf.getObjectValue(txb_DISTR_BAS_MMDD) != "") {
        if ($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).length == 4) {
            if (parseInt($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).substring(0, 2), 10) < 13 && parseInt($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).substring(0, 2), 10) > 0) {
                if (parseInt($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).substring(2, 4), 10) < 32 && parseInt($c.stf.getObjectValue(txb_DISTR_BAS_MMDD).substring(2, 4), 10) > 0) {

                } else {
                    $c.win.alert("올바른 [분배기준일]을 입력하세요.");
                    txb_DISTR_BAS_MMDD.focus();
                    return false;
                }
            } else {
                $c.win.alert("올바른 [분배기준일]을 입력하세요.");
                txb_DISTR_BAS_MMDD.focus();
                return false;
            }
        } else {
            $c.win.alert("올바른 [분배기준일]을 입력하세요.");
            txb_DISTR_BAS_MMDD.focus();
            return false;
        }
        return true;
    } else {
        $c.win.alert("올바른 [분배기준일]을 입력하세요.");
        txb_DISTR_BAS_MMDD.focus();
        return false;
    }
};
scwin.fn_getCreditGrdCd = function() {
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='CREDIT_GRD_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "' ':"; //초기값
    for (k = 1; k <= dts_Cod.getTotalRow(); k++) {
        strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
    }
    return strCbd;
};
scwin.fn_searchLPCode = function() {
    var strCbdLP = "' ':"; //초기값
    dts_LP.DataID = "/listingCommon.do?method=listLeadCom";
    dts_LP.Reset();
    for (k = 1; k <= dts_LP.getTotalRow(); k++) {
        strCbdLP = strCbdLP + (strCbdLP == "" ? "" : ",") + dts_LP.getCellData(k, "VALUE") + ":" + dts_LP.getCellData(k, "TEXT");
    }
    $c.cm.setColumnProp(grd_LP, 'LP_MBR_NO', 'Data', strCbdLP);
};
scwin.fn_SetParZipCd = function(arrPar) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    txb_ZIPCD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_ADDR.setValue((arrPar.length >= 2 ? arrPar[1] : "")); /*ORG SRC: dts_IsuItem.NameValue(1, "ZIPCD_SEQ") = (arrPar.length >= 3 ? arrPar[2] : "");*/ X = (arrPar.length >= 3 ? arrPar[2] : "");
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_SearchIsuCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_SearchIsuNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    arrPar[3] = $c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD);
    arrPar[4] = SEARCH_TYP_SEC; // jackal_11.05.12
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_SearchIsuCd.setValue(arrPar[0].ISU_CD);
        txb_SearchIsuNm.setValue(arrPar[0].ISU_NM);
        //alert("[종목코드]="+arrPar[0].ISU_CD);
        var exemBzProcsNo = arrPar[0].BZ_PROCS_NO; // jackal_11.05.12
        //업무처리번호대신 mktTpCd 값으로도 구분해서 사용할수 있음
        if (exemBzProcsNo == "") {
            //코스닥에서 유가로 업무가 넘어와서 필요없음 
            //fn_getIsuInfo_read_sync(getObjectValue(txb_SearchIsuCd));
            $c.pre_newlisting.fn_getExem_read_sync(arrPar[0].ISU_CD); // jackal_11.05.12

        } else {
            //alert("[예비심사의 업무처리번호]"+exemBzProcsNo);
            //fn_getExem_read_sync(exemBzProcsNo);
            $c.pre_newlisting.fn_getExem_read_sync(arrPar[0].ISU_CD); // jackal_11.05.12

        }
        //데이타셋에 다시한번 settion한다.
        var parentWin = $c.frame.path("../");
        $c.stf.setObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD, scwin.pJsMarket);
        //fn_initLabel(getObjectValue(cmb_SECUGRP_ID));

    }
};




/**
 *기초지수 jackal_23.07.28
 */
scwin.fn_getBasIdxCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    //		arrPar[0] = dts_IsuItem.NameValue(1, "TRST_COM_ISUR_CD");   // 코드값을 포함할 컨트롤
    arrPar[0] = txb_IDX_TOTAL_CD.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_BAS_IDX_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = txb_REF_IDX_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[3] = txb_IDX_LVRG_INVRS_TP_NM; // 추적배수
    arrPar[4] = txb_MKT_TP_CD_L; // 기초시장 대
    arrPar[5] = txb_MKT_TP_CD_M; // 기초시장 중
    arrPar[6] = txb_MKT_TP_CD_S; // 기초시장 소
    arrPar[7] = txb_ULY_TP_CD_L1; // 기초자산1 대
    arrPar[8] = txb_ULY_TP_CD_L1; // 기초자산1 중
    arrPar[9] = txb_ULY_TP_CD_L1; // 기초자산1 소
    arrPar[10] = txb_ULY_TP_CD_L2; // 기초자산2 대
    arrPar[11] = txb_ULY_TP_CD_L2; // 기초자산2 중
    arrPar[12] = txb_ULY_TP_CD_L2; // 기초자산2 소
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *기초지수 jackal_23.07.28
 */
scwin.fn_SetBasIdxCd = function(arrPar) {
    txb_IDX_TOTAL_CD.setValue(arrPar[0].IDX_TOTAL_CD);
    txb_BAS_IDX_NM.setValue(arrPar[0].BAS_IDX_NM);
    txb_BAS_IDX_NM.title = arrPar[0].BAS_IDX_NM;
    txb_REF_IDX_NM.setValue(arrPar[0].REF_IDX_NM);
    txb_REF_IDX_NM.title = arrPar[0].REF_IDX_NM;
    txb_IDX_LVRG_INVRS_TP_NM.setValue(arrPar[0].IDX_LVRG_INVRS_TP_NM); // 추적배수
    txb_MKT_TP_CD_L.setValue(arrPar[0].MKT_TP_NM_L); // 기초시장 대
    txb_MKT_TP_CD_M.setValue(arrPar[0].MKT_TP_NM_M); // 기초시장 중
    txb_MKT_TP_CD_S.setValue(arrPar[0].MKT_TP_NM_S); // 기초시장 소
    txb_ULY_TP_CD_L1.setValue(arrPar[0].ULY_TP_NM_L1); // 기초자산1 대
    txb_ULY_TP_CD_M1.setValue(arrPar[0].ULY_TP_NM_M1); // 기초자산1 중
    txb_ULY_TP_CD_S1.setValue(arrPar[0].ULY_TP_NM_S1); // 기초자산1 소
    txb_ULY_TP_CD_L2.setValue(arrPar[0].ULY_TP_NM_L2); // 기초자산2 대
    txb_ULY_TP_CD_M2.setValue(arrPar[0].ULY_TP_NM_M2); // 기초자산2 중
    txb_ULY_TP_CD_S2.setValue(arrPar[0].ULY_TP_NM_S2); // 기초자산2 소

    dts_IsuItem.setCellData(dts_IsuItem.getRowPosition(), "IDX_CALC_INST_CD", arrPar[0].IDX_CALC_INST_CD);
    dts_IsuItem.setCellData(dts_IsuItem.getRowPosition(), "IDX_MKT_CLSS_ID", arrPar[0].IDX_MKT_CLSS_ID);
    dts_IsuItem.setCellData(dts_IsuItem.getRowPosition(), "IDX_SEQ", arrPar[0].IDX_SEQ);
    dts_IsuItem.setCellData(dts_IsuItem.getRowPosition(), "IDX_LVRG_INVRS_TP_CD", arrPar[0].IDX_LVRG_INVRS_TP_CD);
    dts_IsuItem.setCellData(dts_IsuItem.getRowPosition(), "STRT_DD", arrPar[0].STRT_DD);

    //alert('IDX_TOTAL_CD='+dts_IsuItem.NameValue(1, "IDX_CALC_INST_CD")+' '+dts_IsuItem.NameValue(1, "IDX_MKT_CLSS_ID")+' '+dts_IsuItem.NameValue(1, "IDX_SEQ")+' '+dts_IsuItem.NameValue(1, "IDX_LVRG_INVRS_TP_CD")+' '+dts_IsuItem.NameValue(1, "STRT_DD") );

};




/**
 *위탁회사
 */
scwin.fn_getParTrstComInstCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = dts_IsuItem.getCellData(1, "TRST_COM_ISUR_CD"); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_TRST_COM_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = "ISUR_ALL";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *위탁회사
 */
scwin.fn_SetParTrstComInstCd = function(arrPar) {
    dts_IsuItem.setCellData(1, "TRST_COM_ISUR_CD", arrPar[0]);
    txb_TRST_COM_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};


/**
 *사무관리
 */
