    arrPar[1] = txb_BZ_ADM_COM_NM.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = "ISUR_ALL";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *사무관리
 */
scwin.fn_SetParBzAdmComNm = function(arrPar) {
    dts_IsuItem.setCellData(1, "BZ_ADM_COM_ISUR_CD", arrPar[0]);
    txb_BZ_ADM_COM_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};



/**
 *수탁회사
 */
