/**
 * 업무처리번호가 없는경우 종목마스터에서 정보를 가져온다.
 * 현재 코스닥정보를 가져오는데 사용
 */
scwin.fn_getIsuInfo_read_sync = function(isucd) {
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_KSQ_EXEM_ETF;
    url += "&ISU_CD=" + isucd;
    dts_IsuItem.DataID = encodeURI(url);
    dts_IsuItem.Reset();
};


/**
 * 유가예비심사정보를 가져오는데 사용
 */
scwin.fn_getExem_read_sync = function(exemBzProcsNo) {
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_EXEM_ETF;
    url += "&BZ_PROCS_NO=" + exemBzProcsNo;
    dts_IsuItem.DataID = encodeURI(url);
    dts_IsuItem.Reset();
};
scwin.fn_read_sync = function() {
    var url = "/Newlisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_ETF_ISU;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_IsuItem.DataID = encodeURI(url);
    dts_IsuItem.Reset();
    var url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_LP_MBR_NO;
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_LP.DataID = encodeURI(url);
    dts_LP.Reset();
    scwin.fn_initLpAndDistrPayGridData("N");
};

/**
 *	한글포함된 문자열 널값 및 최대길이 확인	*/
scwin.fn_checkValueNullMaxlength = function(vObj, vTitle) {
    var vMaxLength = vObj.maxLength;
    if ($c.stf.getObjectValue(vObj) == "") {
        $c.win.alert(vTitle + "을 입력하세요.");
        vObj.focus();
        return false;
    }
    if (fn_GetByte(vObj) > vMaxLength) {
        $c.win.alert("[" + vTitle + "] 입력길이가 " + vMaxLength + "자리를 초과할 수 없습니다.");
        vObj.focus();
        return false;
    }
    return true;
};



