scwin.fn_CheckForm = function() {
    fn_GetByte(txb_COM_NM.getValue());
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "") {
        $c.win.alert("[시장구분]을 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == "") {
        $c.win.alert("[유가증권]을 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_SearchIsu.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_SRT_CD) == "") {
        $c.win.alert("[종목단축코드]항목값이  없습니다.");
        txb_ISU_SRT_CD.focus();
        return false;
    }
    if (scwin.TR_JOB == 'I') {
        if ($c.pre_newlisting.fn_checkDoubleInput(dts_DoubleChk, $c.stf.getObjectValue(txb_ISU_CD))) return false;
    }
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_NM, "한글법인명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ABBRV, "한글법인약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ENG_NM, "영문법인명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_COM_ENG_ABBRV, "영문법인약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_KOR_NM, "한글종목명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_KOR_ABBRV, "한글종목약명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_ENG_NM, "영문종목명")) return false;
    if (!scwin.fn_checkValueNullMaxlength(txb_ISU_ENG_ABBRV, "영문종목약명")) return false;
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "1") {
        if ($c.stf.getObjectValue(txb_ISUR_SYMBL) == "") {
            $c.win.alert("[영문법인심볼]을 입력하세요.");
            txb_ISUR_SYMBL.focus();
            return false;
        }
        if ($c.lc.fn_eng_symbl_check($c.stf.getObjectValue(txb_ISUR_SYMBL))) {
            //if (! fn_chkCorpSymblDoubleInput(getObjectValue(txb_ISUR_SYMBL), getObjectValue(txb_ISUR_CD), dts_Symbl)) {
            if (!$c.lc.fn_chkEtfCorpSymblDoubleInput($c.stf.getObjectValue(txb_ISUR_SYMBL), $c.stf.getObjectValue(txb_ISUR_CD), dts_Symbl)) {
                $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                return false;
            }
        } else {
            txb_ISUR_SYMBL.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_ISU_ENG_SYMBL) == "") {
            $c.win.alert("[영문종목심볼]을 입력하세요.");
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
        if ($c.lc.fn_eng_symbl_check($c.stf.getObjectValue(txb_ISU_ENG_SYMBL))) {
            if (!$c.lc.fn_chkIsuSymblDoubleInput($c.stf.getObjectValue(txb_ISU_ENG_SYMBL), $c.stf.getObjectValue(txb_ISUR_CD), dts_Symbl)) {
                $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
                return false;
            }
        } else {
            txb_ISU_ENG_SYMBL.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == SECUGRP_ID_EF) {
        if ($c.stf.getObjectValue(txb_ZIPCD) == "") {
            $c.win.alert("[우편번호]를 선택하세요.");
            img_ZIPCD.focus();
            return false;
        }
    } else if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == SECUGRP_ID_FE) {
        if ($c.stf.getObjectValue(txb_ADDR) == "") {
            $c.win.alert("[주소]를 입력세요.");
            txb_ADDR.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_LIST_NO) == "") {
        $c.win.alert("[상장번호]를 선택하세요.");
        txb_LIST_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CORP_TEL_NO) == "") {
        $c.win.alert("[법인전화번호]을 입력하세요.");
        txb_CORP_TEL_NO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ETF_TP_CD) == "") {
        $c.win.alert("[ETF분류]를 선택하세요.");
        cmb_ETF_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_LIST_DD) == "") {
        $c.win.alert("[상장일]을 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    if (scwin.vCurDate >= $c.stf.getObjectValue(edt_LIST_DD)) {
        $c.win.alert("[상장일]을 현재일이후로 입력하세요.");
        edt_LIST_DD.focus();
        return false;
    }
    // tbld_etf_isu 에 키에 입력되는 항목이라 뺄수 없슴.
    if ($c.stf.getObjectValue(edt_ISU_DD) == "") {
        $c.win.alert("[발행일(설정일)]을 입력하세요.");
        edt_ISU_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_TRST_COM_NM) == "") {
        $c.win.alert("[집합투자업자]을 선택하세요.");
        txb_TRST_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_BZ_ADM_COM_NM) == "") {
        $c.win.alert("[일반사무관리회사]을 입력하세요.");
        txb_BZ_ADM_COM_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_TRST_INST_NM) == "") {
        $c.win.alert("[신탁업자(신탁회사)]을 입력하세요.");
        txb_TRST_INST_NM.focus();
        return false;
    }
    if ($c.pre_newlisting.fn_CheckGridDataset(dts_LP, "LP_MBR_NO")) {
        $c.win.alert("[LP회원명을]을 선택하세요.");
        return false;
    }

    //if(cmb_BAS_IDX_CD.Index < 0  && cmb_REF_IDX_CD.Index <0 ) {
    //	alert("기초지수를 선택하세요.");
    //	cmb_BAS_IDX_CD.Focus();
    //	return false;
    //}

    // 기초지수 및 참조지수 선택 체크 jackal_23.07.28
    // 기초지수(P1)가 없는 경우는 통과시켜줌
    if ($c.stf.getObjectValue(txb_BAS_IDX_NM) == "" && $c.stf.getObjectValue(txb_REF_IDX_NM) == "")
    //if ( getObjectValue(txb_BAS_IDX_NM) == "" || getObjectValue(txb_REF_IDX_NM) == "" )

    {
        $c.win.alert("기초지수를 선택하세요.");
        return false;
    }



    //ETF종목에는 해당되지않는항목
    dts_IsuItem.setCellData(1, "CEO_NM", '-');
    dts_IsuItem.setCellData(1, "STD_IND_CD", '-');
    dts_IsuItem.setCellData(1, "LIST_METHD_TP_CD", LIST_METHD_TP_CD_4);
    dts_IsuItem.setCellData(1, "ISU_RSN_CONTN", "신규상장");
    dts_IsuItem.setCellData(1, "REMK", "");
    return true;
};
scwin.fn_initLpAndDistrPayGridData = function(initYn) {
    $c.pre_newlisting.fn_initLPGridData(dts_LP, initYn);
    //fn_initDistrPayGridData(dts_DISTR_PAY, initYn);

