scwin.fn_setGridDataSet = function() {
    //fn_setLPGridData(dts_LP, vBzProcsNo);
    // jackal_11.05.12 새로운 data set 으로 구성함.
    dts_LP_SAVE.removeAll();
    for (var i = 1; i <= dts_LP.getTotalRow(); i++) {
        var vLpMbrNo = dts_LP.getCellData(i, "LP_MBR_NO");
        if (vLpMbrNo != " " && vLpMbrNo != "") {
            dts_LP_SAVE.insertRow();
            dts_LP_SAVE.setCellData(i, "BZ_PROCS_NO", scwin.vBzProcsNo);
            dts_LP_SAVE.setCellData(i, "LP_MBR_NO", vLpMbrNo);
            dts_LP_SAVE.setCellData(i, "LP_CONTRT_DD", ''); //not null -> null
            dts_LP_SAVE.setCellData(i, "LP_STRT_DD", ''); //not null -> null

        }
    }
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);

        //alert("[bz_procs_no]"+bz_procs_no);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_IsuItem.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            scwin.fn_trs(TR_JOB_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    dts_LP.undoAll();
    //dts_DISTR_PAY.UndoAll();
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TR_JOB_DELETE);
    //alert("dts_IsuItem :"+dts_IsuItem.Text);

};
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    scwin.fn_SaveDistrBasMmDd();
    scwin.fn_setGridDataSet();

    //alert('[dts_IsuItem]'+dts_IsuItem.text);
    trs_Save.Action = $c.lc.fn_encodeNSession("/Newlisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveNewListing");
    trs_Save.KeyName = "toinb_dataid4";
    //trs_Save.KeyValue="JSP(I:pInput=dts_IsuItem, I:pInputLP=dts_LP, I:pInputDistrPay=dts_DISTR_PAY_SAVE, I:pInputCredti=dts_CREDIT_SAVE)";
    // jackal_11.05.12
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuItem, I:pInputLP=dts_LP_SAVE, I:pInputCredti=dts_CREDIT_SAVE)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",SECUGRP_ID=" + $c.stf.getObjectValue(cmb_SECUGRP_ID) + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + dts_IsuItem.getCellData(1, "ISUR_CD") + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_101;
    trs_Save.Post();
};
