scwin.dts_IsuItem_OnLoadCompleted = function(rowcount) {
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('X');
        if ($c.stf.getObjectValue(edt_LIST_DD) > scwin.vCurDate) {
            buttonSet.setUpdateStatus();
        } else {
            buttonSet.setErrorStatus(); //disable 시킨다.

        }
        scwin.fn_getDistrBasMmDd();
    }
    if ($c.stf.getObjectValue(txb_LIST_NO) != "") {
        img_LIST_NO.src = "../img/btn_LstNoCrt_d.gif";
        img_LIST_NO.setDisabled(true);
    }
    scwin.fn_disableDistrMmDd();

    // jackal_23.07.28 
    txb_BAS_IDX_NM.title = dts_IsuItem.getCellData(dts_IsuItem.getRowPosition(), "IDX_NM");
    txb_REF_IDX_NM.title = dts_IsuItem.getCellData(dts_IsuItem.getRowPosition(), "REF_IDX_NM");
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
        parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
    }
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        dts_DISTR_BAS_MMDD.removeAll();
        scwin.fn_read_sync();
    }
    // 신규 저장이되면 값을 입력할수 있게  enable
    if (scwin.vBzProcsNo != "") btn_sim.setDisabled(false); // jackal_11.08.08

};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    if (js_market == "1") {
        $c.stf.showObj(panel_KSE_1, true);
        $c.stf.showObj(panel_KSE_2, true);
        //showObj(panel_KSE_3, true);

    } else if (js_market == "2") {
        $c.stf.showObj(panel_KSE_1, false);
        $c.stf.showObj(panel_KSE_2, false);
        //showObj(panel_KSE_3, false);

    } else {
        scwin.pJsMarket = '1';
    }
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    $c.elw.fn_searchCode();
    scwin.fn_searchLPCode();

    // jackal_23.07.28 팝업창 선택으로 바뀜
    //fn_searchBasIdxClss();	// 기초지수

    dts_LP_SAVE.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NEWLISTING_LP_INOUT";
    dts_LP_SAVE.reset();
    dts_DISTR_BAS_MMDD.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETF_DISTR_BAS_MMDD_INOUT";
    dts_DISTR_BAS_MMDD.reset();
    dts_CREDIT_SAVE.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETF_CREDIT_GRD_NEWLISTING_INOUT";
    dts_CREDIT_SAVE.reset();
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.rowPos = parentWin.dts_List.getFocusedRowIndex();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성



    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
        scwin.fn_initLpAndDistrPayGridData("Y");
        txb_SearchIsuCd.setValue(dts_IsuItem.getCellData(1, "ISU_CD"));
        txb_SearchIsuNm.setValue(dts_IsuItem.getCellData(1, "ISU_KOR_NM"));
        cmb_SECUGRP_ID.setDisabled(true);
        btn_sim.setDisabled(false); // jackal_11.08.08

    } else {
        //fn_initForm("C");

        dts_IsuItem.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETF_ISU_NEWLISTING_INOUT";
        dts_IsuItem.reset();
        dts_IsuItem.insertRow();

        // jackal_23.07.28
        //if(cmb_BAS_IDX_CD.Index <0) {
        // 추적배수
        $c.stf.setObjectValue(txb_IDX_LVRG_INVRS_TP_NM, "");
        // 기초시장
        $c.stf.setObjectValue(txb_MKT_TP_CD_L, "");
        $c.stf.setObjectValue(txb_MKT_TP_CD_M, "");
        $c.stf.setObjectValue(txb_MKT_TP_CD_S, "");
        // 기초자산	
        $c.stf.setObjectValue(txb_ULY_TP_CD_L1, "");
        $c.stf.setObjectValue(txb_ULY_TP_CD_M1, "");
        $c.stf.setObjectValue(txb_ULY_TP_CD_S1, "");
        $c.stf.setObjectValue(txb_ULY_TP_CD_L2, "");
        $c.stf.setObjectValue(txb_ULY_TP_CD_M2, "");
        $c.stf.setObjectValue(txb_ULY_TP_CD_S2, "");
        //}


        dts_LP.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=NEWLISTING_LP_INOUT";
        dts_LP.reset();
        $c.stf.setObjectValue(cmb_SECUGRP_ID, $c.stf.getObjectValue(parentWin.cmb_NEW_SECUGRP_ID)); //부모창에서 증권그룹값이 가져온다.
        $c.stf.setObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD, scwin.pJsMarket);
        scwin.fn_initLpAndDistrPayGridData("N");

        // 신규 저장을 위해 창인 경우 disable
        btn_sim.setDisabled(true); // jackal_11.08.08		

    }
    scwin.fn_initLabel($c.stf.getObjectValue(cmb_SECUGRP_ID));
    scwin.fn_disableDistrMmDd();
};
